
CREATE TABLE region_tax_combinations (
    id INT AUTO_INCREMENT PRIMARY KEY,
    source_region VARCHAR(20),
    target_region VARCHAR(20),
    sector VARCHAR(20),
    clave_regimen VARCHAR(2),
    calificacion_operacion VARCHAR(3),
    exencion_code VARCHAR(10),
    tipo_impositivo VARCHAR(10),
    recargo VARCHAR(10),
    INDEX idx_region_sector (source_region, target_region, sector)
);

